1	// Budget page: how much is left of the monthly budget.
2	function remaining(items, budget) {
3	  let spentCents = 0;
4	  for (const item of items) spentCents = spentCents + Math.round(Number(item.amount) * 100);
5	  return (Math.round(budget * 100) - spentCents) / 100;
6	}
7	module.exports = { remaining };
